"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFeatureContent } from "./components/feature-sections/content";
import View3 from "./components/feature-sections/variants/04-showcase";
const variants = {"showcase":View3};
export type { ArtemisFeatureContent, ArtemisFeatureImage, ArtemisFeatureItem, ArtemisFeatureLink } from "./components/feature-sections/content";
export interface ArtemisFeatureSectionsProps { className?: string; variant?: "showcase"; /** The words on the feature section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFeatureContent>; }
export function ArtemisFeatureSections({ className, variant = "showcase", content }: ArtemisFeatureSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisFeatureLink {
  label: string;
  href: string;
}

/** A picture shown as content, and the words that stand in for it. */
export interface ArtemisFeatureImage {
  src: string;
  alt: string;
}

/** One feature: a row, card, step or tab, depending on the layout. */
export interface ArtemisFeatureItem {
  /** The feature's name. All layouts; signal-grid puts its first word on a line of its own. */
  title: string;
  /** A sentence or two about the feature. All layouts; product-hotspots, steps, tabs and stage-tabs show it for the chosen feature only. */
  description: string;
  /** A short name: the tab in tabs and stage-tabs (which show the title when you leave this out), and the words after the number in alternating-rows. */
  label?: string;
  /** Short points under the description. alternating-rows, product-hotspots and tabs. */
  bullets?: string[];
  /** A figure shown large. voice-ai (first card) and control-deck (third and fourth cards; on the third, a trailing % is set small and fills the bar). */
  stat?: string;
  /** The feature's icon. visual-benefits, signal-grid, voice-ai (first card), control-deck (fourth and fifth cards) and tabs, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
  /** A product picture. tabs, which shows its own picture for that slot when you leave this out. */
  image?: ArtemisFeatureImage;
}

/**
 * The words on an Artemis feature section. Every layout reads this shape, so you can switch layouts and keep them.
 * An empty `badge`, `headlineAccent` or `subhead` leaves that line out.
 */
export interface ArtemisFeatureContent {
  /** A short line above the headline. All layouts except visual-benefits, alternating-rows and stage-tabs. */
  badge?: string;
  /** The section heading. All layouts except stage-tabs. */
  headline?: string;
  /**
   * The second part of the heading. showcase, signal-grid, control-deck, voice-ai, list, bento and tabs put it on a
   * line of its own, steps sets it in the accent color, and the other layouts with a heading run it on after the
   * headline. It goes with `headline`: give a headline without it and the heading has no second part.
   */
  headlineAccent?: string;
  /** A sentence or two under the heading. All layouts except visual-benefits, tabs and stage-tabs. */
  subhead?: string;
  /**
   * The features. All layouts. Today's counts look best: three in visual-benefits, alternating-rows, showcase,
   * benefits-triptych and steps; four in product-hotspots, voice-ai, list, tabs and stage-tabs; five in control-deck
   * (which shows no more than five) and bento; six in signal-grid.
   */
  items: ArtemisFeatureItem[];
  /** The button under the features. visual-benefits. */
  cta?: ArtemisFeatureLink;
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, type Transition, useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useState } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import type { ArtemisFeatureContent } from "../content";
const DEFAULT = {
    badge: "System explanation",
    headline: "One library.",
    headlineAccent: "Every layer covered.",
    subhead: "Artemis gives you the motion, polish, and structure to ship premium interfaces faster — without rebuilding the basics.",
    items: [
        { title: "Assemble a page in minutes", description: "Drop in premium blocks — pricing, hero, footer, CTA — and a full landing page comes together fast." },
        { title: "Source files, fully yours", description: "Every component ships as real source you can read, edit, and own — no black-box dependency." },
        { title: "Install in one command", description: "Add any premium component straight from your private registry with the shadcn CLI." },
    ],
} satisfies ArtemisFeatureContent;
const VIEWPORT = { once: true, margin: "-60px" } as const;
const WORD_HIDDEN = { opacity: 0, filter: "blur(10px)", y: "40%" };
const WORD_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const WORD_STAGGER = 0.09;
function wordTransition(index: number): Transition {
    const delay = index * WORD_STAGGER;
    return {
        opacity: { duration: 0.7, ease: ARTEMIS_EASE_OUT, delay },
        filter: { duration: 0.9, ease: ARTEMIS_EASE_OUT, delay },
        y: { type: "spring", stiffness: 140, damping: 26, mass: 1.2, delay },
    };
}
const CARD_HIDDEN = { opacity: 0, filter: "blur(6px)", y: 24 };
const CARD_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const ITEM_HIDDEN = { opacity: 0, filter: "blur(4px)", y: 10 };
const ITEM_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const itemTransition = (delay: number): Transition => ({ duration: 0.4, ease: ARTEMIS_EASE_OUT, delay });
const CHAT_CYCLE_MS = 5600;
const NAME_CYCLE_MS = 2600;
const TASKS = ["Pricing \u2014 plans grid", "Hero \u2014 code demo", "Footer \u2014 spotlight", "CTA \u2014 gradient FAQ"] as const;
const CHIPS = [
    { name: "pricing.tsx", color: "#3b82f6" },
    { name: "hero.tsx", color: "#10b981" },
    { name: "footer.tsx", color: "#f59e0b" },
] as const;
const FILES = [
    { name: "pricing.tsx", color: "#3b82f6" },
    { name: "hero-code-demo.tsx", color: "#10b981" },
    { name: "footer-spotlight.tsx", color: "#f59e0b" },
    { name: "agent-chat-input.tsx", color: "#f43f5e" },
    { name: "cta-faq.tsx", color: "#06b6d4" },
    { name: "features-tabs.tsx", color: "#2563eb" },
] as const;
const NAMES = ["pricing", "hero-code-demo", "footer-spotlight", "cta-faq", "features-tabs"] as const;
function useReducedAfterMount(): boolean {
    const prefers = useReducedMotion() ?? false;
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    return mounted && prefers;
}
function useTicker(ms: number, enabled: boolean): number {
    const [tick, setTick] = useState(0);
    useEffect(() => {
        if (!enabled)
            return;
        const id = setInterval(() => setTick((t) => t + 1), ms);
        return () => clearInterval(id);
    }, [ms, enabled]);
    return tick;
}
function Item({ as, className, delay, reduce, children }: {
    as: "div" | "p";
    className: string;
    delay: number;
    reduce: boolean;
    children: ReactNode;
}) {
    if (reduce) {
        return as === "p" ? <p className={className}>{children}</p> : <div className={className}>{children}</div>;
    }
    const Tag = as === "p" ? motion.p : motion.div;
    return (<Tag className={className} initial={ITEM_HIDDEN} animate={ITEM_SHOWN} transition={itemTransition(delay)}>
      {children}
    </Tag>);
}
function CheckIcon() {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-2.5" aria-hidden="true">
      <path d="M20 6 9 17l-5-5"/>
    </svg>);
}
function FileCodeIcon() {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-file-code art:size-3.5 art:text-foreground" aria-hidden="true">
      <path d="M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z"/>
      <path d="M14 2v5a1 1 0 0 0 1 1h5"/>
      <path d="M10 12.5 8 15l2 2.5"/>
      <path d="m14 12.5 2 2.5-2 2.5"/>
    </svg>);
}
function CardBackdrop({ src }: {
    src: string;
}) {
    return (<>
      <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:overflow-hidden">
        <img src={src} alt="" width="768" height="768" loading="lazy" decoding="async" className="art:size-full art:object-cover" style={{ objectPosition: "center" }}/>
        <div className="art:absolute art:inset-0 art:bg-background/10 art:dark:bg-background/65"/>
      </div>
      <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:bg-black/15 art:dark:bg-black/20"/>
    </>);
}
function ChatStack({ reduce }: {
    reduce: boolean;
}) {
    const cycle = useTicker(CHAT_CYCLE_MS, !reduce);
    return (<div key={cycle} className="art:flex art:flex-col art:gap-2.5">
      <Item as="div" className="art:max-w-[86%] art:self-end art:rounded-2xl art:rounded-br-sm art:bg-white art:px-3.5 art:py-2 art:font-medium art:text-neutral-900 art:text-xs" delay={0.1} reduce={reduce}>
        {"Add a pricing block and a hero to my landing."}
      </Item>
      <Item as="div" className="art:rounded-2xl art:border art:border-border art:bg-background/90 art:p-3 art:backdrop-blur-md" delay={0.5} reduce={reduce}>
        <div className="art:flex art:flex-col art:gap-2">
          {TASKS.map((task, i) => (<div key={task} className="art:flex art:items-center art:gap-2 art:text-xs art:text-foreground">
              {reduce ? (<span className="art:grid art:size-3.5 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-foreground">
                  <CheckIcon />
                </span>) : (<motion.span className="art:grid art:size-3.5 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-foreground" initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: "spring", visualDuration: 0.2, bounce: 0.34, delay: 0.95 + i * 0.22 }}>
                  <CheckIcon />
                </motion.span>)}
              <span className="art:flex-1 art:truncate">
                {task}
              </span>
            </div>))}
        </div>
        <Item as="p" className="art:mt-2 art:text-xs art:text-foreground/60" delay={1.9} reduce={reduce}>
          {"Four blocks added"}
        </Item>
      </Item>
      <Item as="div" className="art:max-w-[90%] art:self-start art:rounded-2xl art:rounded-bl-sm art:border art:border-border art:bg-background/90 art:px-3.5 art:py-2 art:text-foreground art:text-xs art:backdrop-blur-md" delay={2.3} reduce={reduce}>
        {"Done \u2014 your landing page is assembled."}
      </Item>
      <Item as="div" className="art:flex art:flex-wrap art:gap-1.5" delay={2.7} reduce={reduce}>
        {CHIPS.map((chip) => (<span key={chip.name} className="art:inline-flex art:items-center art:gap-1.5 art:rounded-lg art:border art:border-border art:bg-background/90 art:px-2 art:py-1 art:text-xs art:text-foreground art:backdrop-blur-md">
            <span className="art:size-2 art:rounded-sm" style={{ backgroundColor: chip.color }}/>
            {chip.name}
          </span>))}
      </Item>
    </div>);
}
function FileRow({ name, color }: {
    name: string;
    color: string;
}) {
    return (<div className="art:mb-2.5 art:flex art:items-center art:gap-3 art:rounded-xl art:border art:border-border art:bg-background/90 art:px-3 art:py-2.5 art:backdrop-blur-md">
      <span className="art:grid art:size-7 art:shrink-0 art:place-items-center art:rounded-md" style={{ backgroundColor: color }}>
        <FileCodeIcon />
      </span>
      <span className="art:truncate art:text-foreground art:text-xs">
        {name}
      </span>
    </div>);
}
function FileMarquee() {
    return (<motion.div animate={{ y: ["0%", "-50%"] }} transition={{ duration: 10.2, ease: "linear", repeat: Number.POSITIVE_INFINITY }}>
      {[...FILES, ...FILES].map((file, i) => (<FileRow key={i} name={file.name} color={file.color}/>))}
    </motion.div>);
}
const SWAP: Transition = { duration: 0.28, ease: ARTEMIS_EASE_OUT };
function Terminal({ reduce }: {
    reduce: boolean;
}) {
    const tick = useTicker(NAME_CYCLE_MS, !reduce);
    const name = NAMES[tick % NAMES.length];
    return (<div className="art:w-full art:rounded-2xl art:border art:border-border art:bg-background/95 art:p-4 art:font-mono art:text-foreground art:text-xs art:backdrop-blur-md">
      <div className="art:mb-3 art:flex art:items-center art:gap-1.5">
        <span className="art:size-2.5 art:rounded-full art:bg-background/90"/>
        <span className="art:size-2.5 art:rounded-full art:bg-background/90"/>
        <span className="art:size-2.5 art:rounded-full art:bg-background/90"/>
      </div>
      <p className="art:text-foreground/55">
        {"$ npx shadcn add"}
      </p>
      <div className="art:mt-1 art:flex art:items-center">
        <span className="art:text-foreground/50">
          {"@zeus/ui/"}
        </span>
        <span className="art:relative art:inline-flex art:h-4 art:items-center art:overflow-hidden">
          <AnimatePresence mode="wait" initial={false}>
            <motion.span key={name} className="art:font-medium art:text-foreground" initial={{ opacity: 0, y: 9 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -9 }} transition={SWAP}>
              {name}
            </motion.span>
          </AnimatePresence>
        </span>
        {reduce ? null : (<motion.span className="art:ml-0.5 art:inline-block art:h-3.5 art:w-1.5 art:bg-white art:align-middle" animate={{ opacity: [1, 1, 0, 0] }} transition={{ duration: 1, ease: "linear", repeat: Number.POSITIVE_INFINITY }}/>)}
      </div>
      <div className="art:mt-3 art:flex art:items-center art:gap-2 art:text-primary">
        <span className="art:grid art:size-3.5 art:place-items-center art:rounded-full art:bg-muted art:text-foreground">
          <CheckIcon />
        </span>
        <AnimatePresence mode="wait" initial={false}>
          <motion.span key={name} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={SWAP}>
            {"added "}
            {name}
          </motion.span>
        </AnimatePresence>
      </div>
    </div>);
}
/** Each slot's decorative backdrop. */
const BACKDROPS = ["/assets/artemis/e4eaebedf217b9dd3e83.webp", "/assets/artemis/ab9e0801e9554ff87dab.webp", "/assets/artemis/c4fdc62cded676e0cb0d.webp"];
function CardVisual({ index, reduce }: {
    index: number;
    reduce: boolean;
}) {
    if (index === 0) {
        return (<div className="art:absolute art:inset-0 art:flex art:flex-col art:justify-end art:gap-2.5 art:p-5">
        <ChatStack reduce={reduce}/>
      </div>);
    }
    if (index === 1 && reduce) {
        return (<div className="art:absolute art:inset-0 art:flex art:flex-col art:justify-center art:p-5">
        {FILES.map((file) => (<FileRow key={file.name} name={file.name} color={file.color}/>))}
      </div>);
    }
    if (index === 1) {
        return (<div className="art:absolute art:inset-0 art:flex art:items-center art:p-5">
        <div className="art:relative art:h-[15rem] art:w-full art:overflow-hidden art:[mask-image:linear-gradient(to_bottom,transparent,black_16%,black_84%,transparent)]">
          <FileMarquee />
        </div>
      </div>);
    }
    return (<div className="art:absolute art:inset-0 art:flex art:items-center art:p-5">
      <Terminal reduce={reduce}/>
    </div>);
}
function CardShell({ index, reduce, children }: {
    index: number;
    reduce: boolean;
    children: ReactNode;
}) {
    if (reduce)
        return <div>{children}</div>;
    return (<motion.div initial={CARD_HIDDEN} whileInView={CARD_SHOWN} viewport={VIEWPORT} transition={{ duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: index * 0.1 }}>
      {children}
    </motion.div>);
}
function Word({ index, reduce, children }: {
    index: number;
    reduce: boolean;
    children: ReactNode;
}) {
    if (reduce) {
        return (<span className="art:inline-block art:will-change-transform" style={{ opacity: 1 }}>
        {children}
      </span>);
    }
    return (<motion.span className="art:inline-block art:will-change-transform" initial={WORD_HIDDEN} whileInView={WORD_SHOWN} viewport={VIEWPORT} transition={wordTransition(index)}>
      {children}
    </motion.span>);
}
export default function FeatureSectionsShowcase({ content }: { content?: Partial<ArtemisFeatureContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const lines = [copy.headline, accent].flatMap((text) => (text ? [text.split(/\s+/).filter(Boolean)] : []));
    const reduce = useReducedAfterMount();
    let wordIndex = 0;
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-6xl">
            <div className="art:grid art:gap-6 art:@min-[1024px]/artemis:grid-cols-[1.55fr_1fr] art:@min-[1024px]/artemis:items-end art:@min-[1024px]/artemis:gap-12">
              <div>
                {copy.badge ? (<p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">
                  {copy.badge}
                </p>) : null}
                <h2 className="art:block art:mt-5 art:text-balance art:text-foreground art:tracking-tight art:text-4xl art:font-medium">
                  {lines.map((line, li) => (<span key={li} className="art:block">
                      {line.map((word, i) => {
                const index = wordIndex++;
                return (<Word key={i} index={index} reduce={reduce}>
                            {word}
                            {i < line.length - 1 ? (<span className="art:inline-block art:w-[0.25em] art:overflow-hidden">
                                {"\u00A0"}
                              </span>) : null}
                          </Word>);
            })}
                    </span>))}
                </h2>
              </div>
              {copy.subhead ? (<p className="art:text-pretty art:text-muted-foreground art:text-sm art:leading-7 art:@min-[640px]/artemis:text-base art:@min-[1024px]/artemis:pb-2">
                {copy.subhead}
              </p>) : null}
            </div>
            <div className="art:mt-12 art:grid art:gap-6 art:@min-[640px]/artemis:grid-cols-2 art:@min-[1024px]/artemis:grid-cols-3">
              {copy.items.map((card, i) => (<CardShell key={card.title} index={i} reduce={reduce}>
                  <div className="art:relative art:h-[26rem] art:overflow-hidden art:rounded-2xl">
                    <CardBackdrop src={BACKDROPS[i % BACKDROPS.length]}/>
                    <CardVisual index={i % 3} reduce={reduce}/>
                  </div>
                  <h3 className="art:mt-4 art:font-medium art:text-foreground art:text-xl">
                    {card.title}
                  </h3>
                  <p className="art:mt-1 art:text-pretty art:text-muted-foreground art:text-sm">
                    {card.description}
                  </p>
                </CardShell>))}
            </div>
          </div>
        </section>
      </div>
    </>);
}
